export const abcMainHtml =
  '<div id="overview" class="block-unfold relative pb-5"><h2>Introduction to Annapurna Circuit Trek</h2><p>The Annapurna Circuit is one of the world’s great walks: a long loop from the sub-tropical Marsyangdi valley, through the Tibetan-style villages of Manang, over the 5,416 m Thorong La pass, and down into the rain-shadow of the Kali Gandaki — the deepest gorge on earth. Few treks pack in so much variety: paddy terraces, pine forest, high desert, glaciers, and the shrine of Muktinath, with Annapurna and Dhaulagiri both in sight on the same day.</p><p>Because the route climbs slowly and includes acclimatisation days in Manang, it is challenging but achievable for walkers with a good base of fitness. Our guides arrange the permits, book the teahouses, carry mountain-rescue insurance, and pace the crossing so the pass day starts in the dark, on schedule, and safely.</p></div><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><h2 id="overview-2" class="wp-block-heading">Annapurna Circuit Trek Highlights</h2><ul class="block-list-with-icon list-none pl-0 grid gap-2 is-trip-highlights" style="gap:18px"><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">Cross Thorong La (5,416 m) at sunrise</span></li><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">The Kali Gandaki — the deepest gorge on earth</span></li><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">Muktinath temple, sacred to Hindus and Buddhists alike</span></li><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">Manang’s Tibetan-Buddhist villages and 500-year-old gompa</span></li><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">Hot springs at Tatopani on the way out</span></li><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">Poon Hill sunrise finale over Dhaulagiri and Annapurna</span></li><li class="mt-0 lwi-hl"><svg class="lwi-check" width="20" height="20" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-d000a889"></use></svg><span class="lwi-hl-text">Sub-tropical forest to high desert in a single loop</span></li></ul><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="mbfse-scta mb-6"><span class="mbfse-scta__ico"><svg width="24" height="24" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#i-73aaf65a"></use></svg></span><div><p class="mbfse-scta__title">Want to know more about this trek?</p><p class="mbfse-scta__sub">Chat with us — real trekking experts, not bots.</p><p class="mbfse-scta__proof"><span class="mbfse-scta__dot" aria-hidden="true"><span class="mbfse-scta__ping"></span><span class="mbfse-scta__dotcore"></span></span>Typically replies within 6&ndash;7 hours</p></div></div><div class="block-itinerary"><button class="itn-toggle" data-trigger="accordionShowAll" aria-expanded="false">Show all days<svg width="14" height="14" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 13l5 5 5-5M7 6l5 5 5-5"></path></svg></button><button class="itn-toggle hidden" data-trigger="accordionHideAll" aria-expanded="true">Hide all days<svg width="14" height="14" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 11l5-5 5 5M7 18l5-5 5 5"></path></svg></button></div><div class="acf-innerblocks-container"><h2 id="itinerary" class="wp-block-heading page-title">Annapurna Circuit Trek Itinerary</h2><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-1-drive-kathmandu-to-besisahar-trek-to-bhulbhule" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 1:</strong>&nbsp;Drive Kathmandu to Besisahar, trek to Bhulbhule</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">A long drive along the Trishuli and Marsyangdi rivers to the trailhead and a flat warm-up walk beside the water.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-2-bhulbhule-to-jagat-1-300-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 2:</strong>&nbsp;Bhulbhule to Jagat (1,300 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Through rice terraces and Hindu villages, crossing the river on the long suspension bridge into the first Gurung settlements.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-3-jagat-to-dharapani-1-960-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 3:</strong>&nbsp;Jagat to Dharapani (1,960 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Entering the restricted area of Manang, the valley closes between cliffs and the architecture turns Tibetan.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-4-dharapani-to-chame-2-710-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 4:</strong>&nbsp;Dharapani to Chame (2,710 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Through pine and fir forest with views of Lamjung Himal, reaching the district headquarters at Chame.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-5-chame-to-upper-pisang-3-300-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 5:</strong>&nbsp;Chame to Upper Pisang (3,300 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Along the Paungda Danda rock face — a wall that climbs 1,500 m straight off the river.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-6-upper-pisang-to-manang-3-520-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 6:</strong>&nbsp;Upper Pisang to Manang (3,520 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Past the cave monasteries of Hongde to the main village of Manang and its gompa.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-7-acclimatisation-day-in-manang" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 7:</strong>&nbsp;Acclimatisation day in Manang</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">A rest-day walk to the Gangapurna lake viewpoint, the ice cave, or the old gompa — slow walking, big views.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-8-manang-to-yak-kharka-4-050-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 8:</strong>&nbsp;Manang to Yak Kharka (4,050 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Into the high grazing country, with yaks and blue sheep for company.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-9-yak-kharka-to-thorong-phedi-4-525-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 9:</strong>&nbsp;Yak Kharka to Thorong Phedi (4,525 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">A short day to the base of the pass — early dinner, earlier bed, and a very early start ahead.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-10-cross-thorong-la-5-416-m-to-muktinath-3-800-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 10:</strong>&nbsp;Cross Thorong La (5,416 m) to Muktinath (3,800 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Start in the dark for the switchbacks to the pass, with prayer flags snapping in the wind, then a long descent to the shrine at Muktinath.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-11-muktinath-to-marpha-2-670-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 11:</strong>&nbsp;Muktinath to Marpha (2,670 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Into the Kali Gandaki and the rain-shadow villages of the Thakali people — apple orchards and Marpha’s white houses.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-12-marpha-to-tatopani-1-200-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 12:</strong>&nbsp;Marpha to Tatopani (1,200 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">Down the Kali Gandaki through Ghasa and the waterfalls of Rupse Chhoro to the hot springs.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-13-tatopani-to-ghorepani-2-850-m" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 13:</strong>&nbsp;Tatopani to Ghorepani (2,850 m)</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">The long climb out of the gorge through Shikha to the ridge-top village of Ghorepani.</p></div></div></div></div></div><div class="block-itinerary__item relative pl-10 py-4"><img alt="map point wave icon" width="36" height="36" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Map-Point-Wave.svg" class="absolute -left-2 text-lg z-10 p-2 rounded-full bg-slate-200" decoding="async" /><div class="acf-innerblocks-container"><div class="wp-block-group block-itinerary__item__header cursor-pointer is-layout-flow wp-block-group-is-layout-flow"><h3 id="day-day-14-poon-hill-3-210-m-sunrise-trek-to-nayapul-and-drive-t" class="wp-block-heading has-base-font-size" style="font-style:normal;font-weight:400"><strong>Day 14:</strong>&nbsp;Poon Hill (3,210 m) sunrise, trek to Nayapul and drive to Pokhara</h3></div><div class="wp-block-group block-itinerary__item__details relative has-text-color has-link-color wp-elements-3 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-vertical is-layout-flex wp-block-group-is-layout-flex"><div class="block-icon-text flex gap-2 items-center"><p style="font-size:18px" class="m-0 leading-tight">A dawn climb to Poon Hill for the Dhaulagiri–Annapurna panorama, then down to the road and the drive back to the lake.</p></div></div></div></div></div></div><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><h2 id="includes" class="wp-block-heading page-title">Includes</h2><div class="wp-block-group has-global-padding is-layout-constrained wp-block-group-is-layout-constrained"><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">Licensed, English-speaking circuit trekking guide</span><span class="inc-desc">A guide who has walked the circuit many times and knows the teahouses and pacing.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">ACAP and Manang restricted-area permits</span><span class="inc-desc">All permits arranged and paid for, including the restricted-area permit for Manang.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">All teahouse lodge bookings (twin sharing)</span><span class="inc-desc">Rooms reserved ahead on the trail so you never walk without a bed.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">Transport Kathmandu–Besisahar and Nayapul–Pokhara</span><span class="inc-desc">Private transport to the trailhead and away from the finish.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">Three meals a day on the trek</span><span class="inc-desc">Breakfast, lunch and dinner at the lodges while on the trail.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">Porter option on request</span><span class="inc-desc">A porter can carry your main bag so you walk light.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><use href="#i-07c8df47"></use></svg></span><span class="inc-body"><span class="inc-title">Mountain rescue insurance, first aid and oximeter checks</span><span class="inc-desc">Daily altitude checks and evacuation cover for the high pass.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /></div><h2 class="wp-block-heading page-title mbfse-excludes-title" id="excludes">Excludes</h2><div class="wp-block-group is-layout-constrained mbfse-excludes-group"><div class="block-icon-text flex gap-2 is-includes is-excluded"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><use href="#i-cd77b4ac"></use></svg></span><span class="inc-body"><span class="inc-title">Nepal visa fee</span><span class="inc-desc">Arranged on arrival at Kathmandu airport — bring USD cash or card.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes is-excluded"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><use href="#i-cd77b4ac"></use></svg></span><span class="inc-body"><span class="inc-title">International flights</span><span class="inc-desc">Flights to and from Kathmandu are booked separately.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes is-excluded"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><use href="#i-cd77b4ac"></use></svg></span><span class="inc-body"><span class="inc-title">Travel and evacuation insurance</span><span class="inc-desc">Required for high-altitude treks; make sure it covers your maximum altitude.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes is-excluded"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><use href="#i-cd77b4ac"></use></svg></span><span class="inc-body"><span class="inc-title">Lunch and dinner in Kathmandu and Pokhara</span><span class="inc-desc">Meals off the trail are at your own cost.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes is-excluded"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><use href="#i-cd77b4ac"></use></svg></span><span class="inc-body"><span class="inc-title">Personal gear and expenses</span><span class="inc-desc">Down jacket, sleeping bag, drinks, snacks and souvenirs.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /><div class="block-icon-text flex gap-2 is-includes is-excluded"><span class="inc-chip" aria-hidden="true"><svg width="18" height="18" viewbox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><use href="#i-cd77b4ac"></use></svg></span><span class="inc-body"><span class="inc-title">Tips for guide and porter</span><span class="inc-desc">Tipping is customary but entirely at your discretion.</span></span></div><hr class="wp-block-separator has-alpha-channel-opacity is-style-default" /></div><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><h2 id="tripdetails" class="wp-block-heading page-title">Read before you book Annapurna Circuit Trek</h2><p class="wp-block-paragraph">Thinking about the Annapurna Circuit Trek? Before you decide, take a few minutes to read this guide. We’ve put together the important things you need to know.</p><p class="wp-block-paragraph">Still not sure if this trek is the right one for you? Send us a message by email or WhatsApp — we’re always happy to help and reply within 24 hours.</p><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group read-before-section has-global-padding is-layout-constrained wp-block-group-is-layout-constrained"><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">A Typical Day on the Annapurna Circuit Trek</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">A trekking day starts early, after breakfast around 7–8 am. You walk for three to five hours before stopping for lunch, then continue for another two to four hours to the day’s village. Walking is steady rather than rushed, and your guide sets the pace to the group. Afternoons are free to rest, explore the village, or walk a little higher for the views. Rest days and acclimatisation days are built into the schedule where the altitude demands them.</p></div></div></div><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">Trek Difficulty</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">The highest point of the Annapurna Circuit Trek is 5,416 m / 17,769 ft, and the route is graded challenging. You walk on well-established trails for 14 days, with a good level of fitness required for consecutive days of walking. No technical climbing or previous high-altitude experience is needed for this grade, but some hill-walking beforehand will make the trip more enjoyable. We pace the route to allow for acclimatisation and carry a first-aid kit and pulse oximeter for daily altitude checks.</p></div></div></div><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">Permits Required</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">The permits required for the Annapurna Circuit Trek are: ACAP and Manang restricted-area permits. These are arranged by us before you start, and the fees are included in your trip price — you do not need to organise anything yourself. Bring your passport and a passport-sized photo; we handle the paperwork. Your guide carries the permits and conservation cards on the trail and they are checked at the relevant gates.</p></div></div></div><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">Best Time to Trek</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">The best seasons for the Annapurna Circuit Trek are March–May and September–November. These months bring the most stable weather and the clearest mountain views. Autumn (after the monsoon) offers the sharpest panoramas and comfortable daytime temperatures; spring brings rhododendron in bloom on the lower slopes. Winter is cold at altitude but often clear, while the summer monsoon brings rain and cloud. Your guide will advise on current conditions before you start.</p></div></div></div><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">Accommodation and Meals</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">Accommodation is in simple, clean teahouse lodges along the route, usually twin-sharing with shared bathrooms. Dining rooms are warm and serve hearty meals — the staple is dal bhat, with pasta, noodles and rice also available. Hot showers and device charging cost a small fee at most villages. We book lodges ahead in peak season so you are never left without a room, and provide a sleeping bag for higher nights where lodges are sparse.</p></div></div></div><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">What to Pack</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">Pack layered clothing for a wide range of conditions, broken-in hiking boots, a warm down jacket, a waterproof shell, sun hat and sunscreen, and a warm hat and gloves for the cold mornings and high passes. A duffel bag for your main gear (carried by porter or pack animal) and a small daypack for water, camera and layers are ideal. We provide a full packing list on booking, and down jackets and sleeping bags are available to rent.</p></div></div></div><div class="block-collapse rounded-md border bg-white"><div class="block-icon-text flex gap-2 block-collapse__header relative cursor-pointer py-5 px-4 pr-14 text-lg bg-slate-50 rounded-t-md items-center"><img alt="routing icon" width="20" height="20" src="https://cdn-ildnegm.nitrocdn.com/KXxKXooeoKkfrapbonFlAAfUPSzqadeE/assets/images/source/rev-8e0b3ac/www.magicalnepal.com/wp-content/uploads/2024/08/Routing.svg" decoding="async" /><h3 style="font-size:20px;font-weight:600" class="m-0 leading-tight">Travel Insurance</h3></div><div class="wp-block-group block-collapse__details relative overflow-hidden transition-height delay-75 ease-in-out has-text-color has-link-color wp-elements-35 is-layout-flow wp-block-group-is-layout-flow" style="color:#596981;font-size:clamp(.875rem,.875rem + ((1vw - .2rem) * .104),.94rem);line-height:1.7"><div class="wp-block-group block-collapse__wrapper p-4 is-layout-flow wp-block-group-is-layout-flow"><p class="wp-block-paragraph">Travel insurance is mandatory for this trek and must cover emergency helicopter evacuation and treatment at up to 5,416 m. Standard policies that exclude high altitude will not be valid, so check the small print before you buy. Bring your policy number and our 24-hour emergency contact with you; your guide carries a satellite-connected phone and a first-aid kit on the trail.</p></div></div></div></div><div style="height:var(--wp--preset--spacing--30)" aria-hidden="true" class="wp-block-spacer"></div><div class="wp-block-group is-layout-constrained wp-block-group-is-layout-constrained"><h2 id="map" class="wp-block-heading page-title">Annapurna Circuit Trek Map</h2><figure class="wp-block-image aligncenter size-full is-resized has-custom-border w-full [&amp;&gt;img]:!w-full"><img width="900" height="568" alt="Annapurna Circuit Trek route map" loading="lazy" decoding="async" style="border-radius:8px;aspect-ratio:1.7777777777778;object-fit:cover;width:800px;height:auto" src="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80" /></figure></div>';
